import React from "react";
import Video from "../../Video/Video";

function SectionComopnent({ title, video, para }) {
  return (
    <div className=" relative top-5 md:flex">
        <div className=" bg-slate-500 justify-center items-center flex flex">
          <h1 className=" text-4xl text-center  text-yellow-400">{title}</h1>
          <p>{para}</p>
        </div>
        <Video video={video} />
    </div>
  );
}

export default SectionComopnent;
